-- AutoEd ERP port: business functions (fees, receipts, approvals, portal, HR, transport, gate).
-- GENERATED by scripts/gen-erp.mjs (schema/erp-tables.mjs, schema/erp-roles.mjs, schema/erp-sql/*.sql). Edit those, not this file.

-- ---------------------------------------------------------------- 10_notify_audit.sql
-- Notification helpers, view logging, and the private gate-pass OTP table.
-- ERP notifications are rows of core.notifications (one inbox for all products; delivery by the outbox/job runner).

-- Gate pass OTPs live in private (decision: never exposed through the Data API; ERP gate_pass_secrets -> private.gate_pass_otps).
create table private.gate_pass_otps (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references core.organizations(id) on delete cascade,
  pass_id uuid not null,
  student_id uuid not null,
  otp text not null check (otp ~ '^[0-9]{6}$'),
  created_at timestamptz not null default now(),
  unique (org_id, pass_id),
  foreign key (org_id, pass_id) references erp.gate_passes(org_id, id) on delete cascade,
  foreign key (org_id, student_id) references core.students(org_id, id) on delete cascade
);
create index gate_pass_otps_student on private.gate_pass_otps(org_id, student_id);
alter table private.gate_pass_otps enable row level security;
comment on table private.gate_pass_otps is 'OTP handed to the guardian for an approved gate pass. No policies: read only through erp.my_gate_pass_otp() and erp.verify_gate_pass().';

-- One notification for one user (no-op for a null user).
create or replace function erp.notify_user(p_org uuid, p_user uuid, p_event text, p_title text, p_body text default null, p_link text default null)
returns void language sql volatile security definer set search_path = '' as $$
  insert into core.notifications (org_id, user_id, product_key, event_key, title, body, link)
  select p_org, p_user, 'erp', p_event, p_title, p_body, p_link
  where p_user is not null and exists (select 1 from core.org_users u where u.org_id = p_org and u.user_id = p_user)
$$;

-- Every guardian with a login in the learner's household (and the learner's own login).
create or replace function erp.notify_guardians(p_student uuid, p_event text, p_title text, p_body text default null, p_link text default null)
returns void language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s core.students;
begin
  select * into v_s from core.students s where s.id = p_student;
  if not found then return; end if;
  insert into core.notifications (org_id, user_id, product_key, event_key, title, body, link)
  select v_s.org_id, g.user_id, 'erp', p_event, p_title, p_body, p_link
    from core.guardians g
   where g.org_id = v_s.org_id and g.household_id = v_s.household_id and g.user_id is not null and g.deleted_at is null;
end $$;

-- Every active user holding one of the given ERP roles (optionally within a branch).
create or replace function erp.notify_roles(p_org uuid, p_roles text[], p_branch uuid, p_event text, p_title text, p_body text default null, p_link text default null)
returns void language sql volatile security definer set search_path = '' as $$
  insert into core.notifications (org_id, user_id, product_key, event_key, title, body, link)
  select p_org, a.user_id, 'erp', p_event, p_title, p_body, p_link
    from core.user_product_access a
    join core.org_users u on u.org_id = a.org_id and u.user_id = a.user_id and u.status = 'active'
   where a.org_id = p_org and a.product_key = 'erp' and a.revoked_at is null and a.role_key = any(p_roles)
     and (p_branch is null or u.home_branch_id is null or u.home_branch_id = p_branch)
$$;

-- Every view of sensitive data is logged (DM-05). A free-text entity name is not accepted: it must be an erp table.
create or replace function erp.log_view(p_entity text, p_id uuid, p_note text default null) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
begin
  if v_org is null or not app.user_has_product(v_org, 'erp') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_entity is null or p_entity !~ '^[a-z_]+$' or to_regclass('erp.' || p_entity) is null then
    raise exception 'unknown entity' using errcode = '22023';
  end if;
  insert into audit.log (org_id, actor_user_id, support_session_id, action, schema_name, table_name, row_id, detail)
  values (v_org, app.uid(), app.support_session_id(), 'erp.view', 'erp', p_entity, p_id, jsonb_build_object('note', left(p_note, 500)));
end $$;

-- ---------------------------------------------------------------- 20_guards.sql
-- Guards and listeners that need the tables: assessments, vouchers, staff exits.

-- A locked or published assessment cannot be reopened or deleted by hand (unlock = approved request, erp.apply_approval).
create or replace function erp.guard_assessment() returns trigger
language plpgsql set search_path = '' as $$
begin
  if not erp.is_request_role() then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    if old.status in ('locked', 'published') and not (pg_trigger_depth() > 1 and not erp.org_exists(old.org_id)) then
      raise exception 'A locked or published assessment cannot be deleted.' using errcode = '42501';
    end if;
    return old;
  end if;
  if old.status in ('locked', 'published') and new.status in ('open', 'submitted') then
    raise exception 'Marks are locked after publication. Request an unlock with a reason.' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger trg_guard_assessment before update or delete on erp.assessments for each row execute function erp.guard_assessment();

-- A voucher must balance: checked at commit, so the lines can be inserted one by one.
create or replace function erp.check_voucher_balanced() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_d numeric;
  v_c numeric;
begin
  select coalesce(sum(l.debit), 0), coalesce(sum(l.credit), 0) into v_d, v_c
    from erp.voucher_lines l where l.org_id = new.org_id and l.voucher_id = new.voucher_id;
  if v_d <> v_c then
    raise exception 'voucher is not balanced: debit % credit %', v_d, v_c using errcode = '23514';
  end if;
  return null;
end $$;
create constraint trigger trg_voucher_balanced after insert on erp.voucher_lines
  deferrable initially deferred for each row execute function erp.check_voucher_balanced();

-- Exit and settlement (HR): on notice the staff member is "on_notice"; when settled they have left (core.staff, via this
-- listener: ERP writes only these two columns of core.staff).
create or replace function erp.on_staff_exit() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.status = 'settled' then
    update core.staff set status = 'left', left_on = coalesce(left_on, new.last_working_day, current_date)
     where id = new.staff_id and org_id = new.org_id and status <> 'left';
  elsif new.status = 'notice' then
    update core.staff set status = 'on_notice' where id = new.staff_id and org_id = new.org_id and status = 'active';
  end if;
  return null;
end $$;
create trigger trg_staff_exit after insert or update of status on erp.staff_exits for each row execute function erp.on_staff_exit();

-- ---------------------------------------------------------------- 30_fees.sql
-- Fee collection (FEE-04, TEC-02): atomic, idempotent, traceable to the ledger. Port of the ERP's collect_fee,
-- reverse_receipt, bounce_cheque and apply_concession (004_logic_core.sql) onto core.* and the platform helpers.
-- Receipts, payments, allocations and vouchers have no insert policy: they are written only by these functions.

-- ---------------------------------------------------------------- numbering (one receipt series in core.number_series, OQ-16)
-- Next receipt number of a branch: 'RCPT-<branch code>-00001'. Creates the branch series on first use. Locks the row.
create or replace function erp.next_receipt_no(p_org uuid, p_branch uuid) returns text
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_code text;
  v_s core.number_series;
begin
  select b.code into v_code from core.branches b where b.org_id = p_org and b.id = p_branch;
  insert into core.number_series (org_id, branch_id, key, prefix, padding, product_key)
  values (p_org, p_branch, 'receipt', 'RCPT-' || coalesce(v_code, 'X') || '-', 5, 'erp')
  on conflict do nothing;
  select * into v_s from core.number_series s
   where s.org_id = p_org and s.key = 'receipt' and s.branch_id is not distinct from p_branch and s.academic_year_id is null
   for update;
  update core.number_series set next_value = next_value + 1 where id = v_s.id;
  return v_s.prefix || lpad(v_s.next_value::text, v_s.padding, '0') || v_s.suffix;
end $$;

-- ---------------------------------------------------------------- ledger
-- Voucher for a receipt: debit cash/bank by payment mode, credit the income account of each fee head. Needs the
-- default accounts 1000 cash, 1010 bank and 4000 fee income (erp.setup_org); without them nothing is posted.
create or replace function erp.post_receipt_voucher(p_receipt uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  r erp.receipts;
  v uuid;
  v_cash uuid;
  v_bank uuid;
  v_inc uuid;
begin
  select * into r from erp.receipts where id = p_receipt;
  select id into v_cash from erp.accounts where org_id = r.org_id and code = '1000';
  select id into v_bank from erp.accounts where org_id = r.org_id and code = '1010';
  select id into v_inc from erp.accounts where org_id = r.org_id and code = '4000';
  if v_cash is null or v_bank is null or v_inc is null then return; end if;
  insert into erp.vouchers (org_id, branch_id, voucher_no, date, type, narration, ref_type, ref_id)
  values (r.org_id, r.branch_id, 'V-' || r.receipt_no, r.date, 'receipt', 'Fee receipt ' || r.receipt_no, 'receipt', r.id)
  returning id into v;
  insert into erp.voucher_lines (org_id, branch_id, voucher_id, account_id, debit)
  select r.org_id, r.branch_id, v, case when rp.mode = 'cash' then v_cash else v_bank end, sum(rp.amount)
    from erp.receipt_payments rp where rp.receipt_id = r.id group by case when rp.mode = 'cash' then v_cash else v_bank end;
  insert into erp.voucher_lines (org_id, branch_id, voucher_id, account_id, credit)
  select r.org_id, r.branch_id, v, coalesce(h.account_id, v_inc), sum(ra.amount)
    from erp.receipt_allocations ra
    join erp.fee_demands d on d.id = ra.demand_id
    join erp.fee_heads h on h.id = d.head_id
   where ra.receipt_id = r.id group by coalesce(h.account_id, v_inc);
end $$;

-- ---------------------------------------------------------------- posting (internal; permission checks are in the wrappers)
-- p = { idempotency_key?, date?, channel?, note?, allocations: [{demand_id, amount}], payments: [{mode, amount, reference?, ...}] }
-- One receipt per learner. Repeating the same idempotency_key returns the earlier receipts.
create or replace function erp.post_receipts(p_org uuid, p jsonb, p_actor uuid, p_actor_name text) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_allocs jsonb := coalesce(p->'allocations', '[]'::jsonb);
  v_pays jsonb := coalesce(p->'payments', '[]'::jsonb);
  v_key text := nullif(p->>'idempotency_key', '');
  v_total numeric := 0;
  v_paytotal numeric;
  a jsonb;
  d erp.fee_demands;
  bal numeric;
  v_students uuid[];
  sid uuid;
  v_receipt uuid;
  v_no text;
  v_ids uuid[] := '{}';
  stotal numeric;
  pay jsonb;
  rem numeric[];
  remaining numeric;
  share numeric;
  v_year uuid;
  v_branch uuid;
  v_hh uuid;
  i integer;
begin
  if v_key is not null and exists (select 1 from erp.receipts where org_id = p_org and idempotency_key = v_key) then
    return jsonb_build_object('duplicate', true, 'receipt_ids',
      (select jsonb_agg(id) from erp.receipts where org_id = p_org and idempotency_key = v_key));
  end if;
  if jsonb_typeof(v_allocs) <> 'array' or jsonb_typeof(v_pays) <> 'array' then
    raise exception 'allocations and payments must be lists' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(v_allocs) x group by x->>'demand_id' having count(*) > 1) then
    raise exception 'Each fee can appear only once in a payment.' using errcode = '22023';
  end if;
  for a in select * from jsonb_array_elements(v_allocs) loop
    select * into d from erp.fee_demands where id = (a->>'demand_id')::uuid and org_id = p_org for update;
    if d.id is null then raise exception 'Fee demand not found.' using errcode = '22023'; end if;
    if d.status in ('cancelled', 'waived') then
      raise exception '% is % and cannot be collected.', coalesce(d.label, 'This fee'), d.status using errcode = '22023';
    end if;
    bal := d.amount - d.concession + d.fine - d.paid;
    if (a->>'amount')::numeric <= 0 or (a->>'amount')::numeric > bal then
      raise exception 'The amount for % is more than its balance of %.', coalesce(d.label, 'a fee'), bal using errcode = '22023';
    end if;
    v_total := v_total + (a->>'amount')::numeric;
  end loop;
  select coalesce(sum((x->>'amount')::numeric), 0) into v_paytotal from jsonb_array_elements(v_pays) x;
  if v_total <= 0 then raise exception 'Nothing to collect.' using errcode = '22023'; end if;
  if v_paytotal <> v_total then
    raise exception 'Payment modes add up to % but the fees selected add up to %.', v_paytotal, v_total using errcode = '22023';
  end if;
  select array_agg(distinct d2.student_id) into v_students
    from jsonb_array_elements(v_allocs) x join erp.fee_demands d2 on d2.id = (x->>'demand_id')::uuid and d2.org_id = p_org;
  select array_agg((x->>'amount')::numeric order by ord) into rem from jsonb_array_elements(v_pays) with ordinality as t(x, ord);

  foreach sid in array v_students loop
    select sum((x->>'amount')::numeric), (array_agg(d2.academic_year_id))[1] into stotal, v_year
      from jsonb_array_elements(v_allocs) x join erp.fee_demands d2 on d2.id = (x->>'demand_id')::uuid and d2.org_id = p_org
     where d2.student_id = sid;
    select s.branch_id, s.household_id into v_branch, v_hh from core.students s where s.id = sid and s.org_id = p_org;
    v_no := erp.next_receipt_no(p_org, v_branch);
    insert into erp.receipts (org_id, branch_id, academic_year_id, receipt_no, student_id, household_id, date, total,
                              collected_by_name, collected_by_user_id, idempotency_key, channel, note)
    values (p_org, v_branch, v_year, v_no, sid, v_hh, coalesce(nullif(p->>'date', '')::date, current_date), stotal,
            p_actor_name, p_actor, v_key, coalesce(p->>'channel', 'counter'), p->>'note')
    returning id into v_receipt;
    v_ids := v_ids || v_receipt;
    for a in select x from jsonb_array_elements(v_allocs) x join erp.fee_demands d2 on d2.id = (x->>'demand_id')::uuid and d2.org_id = p_org where d2.student_id = sid loop
      insert into erp.receipt_allocations (org_id, receipt_id, demand_id, student_id, amount)
      values (p_org, v_receipt, (a->>'demand_id')::uuid, sid, (a->>'amount')::numeric);
      update erp.fee_demands set paid = paid + (a->>'amount')::numeric,
             status = case when paid + (a->>'amount')::numeric >= amount - concession + fine then 'paid' else 'partial' end
       where id = (a->>'demand_id')::uuid;
    end loop;
    remaining := stotal;
    for i in 1..coalesce(array_length(rem, 1), 0) loop
      exit when remaining <= 0;
      if rem[i] > 0 then
        share := least(rem[i], remaining);
        pay := v_pays -> (i - 1);
        insert into erp.receipt_payments (org_id, receipt_id, mode, amount, reference, cheque_no, cheque_bank, cheque_date, cheque_status, gateway, gateway_payment_id)
        values (p_org, v_receipt, pay->>'mode', share, pay->>'reference', pay->>'cheque_no', pay->>'cheque_bank',
                nullif(pay->>'cheque_date', '')::date, case when pay->>'mode' in ('cheque', 'dd') then 'received' end,
                pay->>'gateway', pay->>'gateway_payment_id');
        rem[i] := rem[i] - share;
        remaining := remaining - share;
      end if;
    end loop;
    perform erp.post_receipt_voucher(v_receipt);
    perform erp.notify_guardians(sid, 'fees.receipt', 'Payment received', 'Receipt ' || v_no || ' for Rs ' || stotal, '/receipt/' || v_receipt);
  end loop;
  return jsonb_build_object('duplicate', false, 'receipt_ids', to_jsonb(v_ids));
end $$;

-- Counter collection by staff with fees.create for every learner's branch.
create or replace function erp.collect_fee(p jsonb) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  v_sid uuid;
  v_branch uuid;
begin
  if v_org is null or not app.user_has_product(v_org, 'erp') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  for v_sid, v_branch in
    select distinct d.student_id, s.branch_id
      from jsonb_array_elements(coalesce(p->'allocations', '[]'::jsonb)) x
      join erp.fee_demands d on d.org_id = v_org and d.id = (x->>'demand_id')::uuid
      join core.students s on s.org_id = d.org_id and s.id = d.student_id
  loop
    if not app.can('erp', 'fees', 'create', v_org, v_branch, null) then
      raise exception 'You do not have permission to collect fees.' using errcode = '42501';
    end if;
  end loop;
  return erp.post_receipts(v_org, p, app.uid(), (select u.display_name from core.org_users u where u.user_id = app.uid()));
end $$;

-- Reversal: marks the receipt reversed, gives the money back to the demands, posts the mirror voucher. Internal: it is
-- reached through an approved receipt_reversal request (erp.apply_approval) or erp.bounce_cheque.
create or replace function erp.reverse_receipt(p_receipt uuid, p_reason text) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  r erp.receipts;
  v uuid;
begin
  select * into r from erp.receipts where id = p_receipt for update;
  if r.id is null or r.status = 'reversed' then return; end if;
  update erp.receipts set status = 'reversed', reversed_reason = p_reason where id = r.id;
  update erp.fee_demands d set paid = d.paid - ra.amount,
         status = case when d.paid - ra.amount <= 0 then 'due' else 'partial' end
    from erp.receipt_allocations ra where ra.receipt_id = r.id and ra.demand_id = d.id;
  if exists (select 1 from erp.vouchers where ref_type = 'receipt' and ref_id = r.id) then
    insert into erp.vouchers (org_id, branch_id, voucher_no, date, type, narration, ref_type, ref_id)
    values (r.org_id, r.branch_id, 'V-REV-' || r.receipt_no, current_date, 'journal',
            'Reversal of ' || r.receipt_no || ': ' || coalesce(p_reason, ''), 'receipt_reversal', r.id)
    returning id into v;
    insert into erp.voucher_lines (org_id, branch_id, voucher_id, account_id, debit, credit)
    select vl.org_id, vl.branch_id, v, vl.account_id, vl.credit, vl.debit
      from erp.voucher_lines vl join erp.vouchers vo on vo.id = vl.voucher_id
     where vo.ref_type = 'receipt' and vo.ref_id = r.id;
  end if;
  perform erp.notify_guardians(r.student_id, 'fees.receipt_reversed', 'Receipt cancelled',
    'Receipt ' || r.receipt_no || ' was reversed: ' || coalesce(p_reason, ''), '/receipt/' || r.id);
end $$;

create or replace function erp.bounce_cheque(p_payment uuid, p_fine numeric default 0) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  rp erp.receipt_payments;
  r erp.receipts;
  fh uuid;
begin
  select * into rp from erp.receipt_payments where id = p_payment and org_id = v_org;
  if rp.id is null or rp.mode not in ('cheque', 'dd') then raise exception 'Cheque payment not found.' using errcode = '22023'; end if;
  select * into r from erp.receipts where id = rp.receipt_id;
  if not app.can('erp', 'fees', 'edit', v_org, r.branch_id, null) then
    raise exception 'You do not have permission to record a bounced cheque.' using errcode = '42501';
  end if;
  if coalesce(p_fine, 0) < 0 then raise exception 'The fine cannot be negative.' using errcode = '22023'; end if;
  update erp.receipt_payments set cheque_status = 'bounced' where id = rp.id;
  perform erp.reverse_receipt(r.id, 'Cheque ' || coalesce(rp.cheque_no, '') || ' bounced');
  if p_fine > 0 then
    select id into fh from erp.fee_heads where org_id = r.org_id and type = 'fine' limit 1;
    if fh is not null then
      insert into erp.fee_demands (org_id, branch_id, academic_year_id, student_id, head_id, label, amount, due_date, note)
      values (r.org_id, r.branch_id, r.academic_year_id, r.student_id, fh, 'Cheque bounce charge', p_fine, current_date, 'Cheque ' || coalesce(rp.cheque_no, ''));
    end if;
  end if;
  perform erp.notify_roles(r.org_id, array['accounts'], r.branch_id, 'fees.cheque_bounced', 'Cheque bounced',
    'Receipt ' || r.receipt_no || ' was reversed. Follow up with the family.', '/fees/cheques');
end $$;

-- Applies an approved concession to the learner's open demands of the matching head type, oldest first.
create or replace function erp.apply_concession(p_id uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  c erp.concessions;
  ht text;
  tot numeric := 0;
  dem record;
  cut numeric;
  rem numeric;
begin
  select * into c from erp.concessions where id = p_id;
  select ct.head_type into ht from erp.concession_types ct where ct.id = c.type_id;
  ht := coalesce(nullif(ht, ''), 'tuition');
  rem := c.value;
  for dem in
    select d.* from erp.fee_demands d join erp.fee_heads h on h.id = d.head_id
     where d.org_id = c.org_id and d.student_id = c.student_id and d.status in ('due', 'partial') and h.type = ht
       and (c.academic_year_id is null or d.academic_year_id = c.academic_year_id)
     order by d.due_date
  loop
    if c.kind = 'percent' then
      cut := round(dem.amount * c.value / 100);
    else
      cut := least(rem, dem.amount - dem.concession - dem.paid);
      rem := rem - greatest(cut, 0);
    end if;
    cut := greatest(least(cut, dem.amount - dem.concession - dem.paid), 0);
    if cut > 0 then
      update erp.fee_demands set concession = concession + cut,
             status = case when amount - (concession + cut) + fine - paid <= 0 then (case when paid > 0 then 'paid' else 'waived' end) else status end
       where id = dem.id;
      tot := tot + cut;
    end if;
  end loop;
  update erp.concessions set amount = tot where id = p_id;
end $$;

-- ---------------------------------------------------------------- online payment (Razorpay, family portal)
-- The family never inserts a payment order: it asks for one here, and the amounts are checked against the balances.
create or replace function erp.create_payment_order(p_student uuid, p_allocations jsonb) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  v_s core.students;
  a jsonb;
  d erp.fee_demands;
  v_total numeric := 0;
  v_id uuid;
begin
  if v_org is null or not app.user_has_product(v_org, 'erp') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into v_s from core.students s where s.id = p_student and s.org_id = v_org;
  if not found or not (p_student = any(app.my_learner_ids()) or app.can('erp', 'fees', 'create', v_org, v_s.branch_id, null)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if jsonb_typeof(p_allocations) <> 'array' or jsonb_array_length(p_allocations) = 0 then
    raise exception 'Choose at least one fee.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(p_allocations) x group by x->>'demand_id' having count(*) > 1) then
    raise exception 'Each fee can appear only once.' using errcode = '22023';
  end if;
  for a in select * from jsonb_array_elements(p_allocations) loop
    select * into d from erp.fee_demands where id = (a->>'demand_id')::uuid and org_id = v_org and student_id = p_student;
    if d.id is null or d.status in ('cancelled', 'waived', 'paid') then raise exception 'That fee cannot be paid.' using errcode = '22023'; end if;
    if (a->>'amount')::numeric <= 0 or (a->>'amount')::numeric > d.amount - d.concession + d.fine - d.paid then
      raise exception 'The amount is more than the balance.' using errcode = '22023';
    end if;
    v_total := v_total + (a->>'amount')::numeric;
  end loop;
  insert into erp.payment_orders (org_id, student_id, amount, allocations, gateway, status)
  values (v_org, p_student, v_total, p_allocations, 'razorpay', 'created') returning id into v_id;
  return v_id;
end $$;

-- Called by the ERP server when the gateway confirms the payment (webhook), never by a school user.
create or replace function erp.settle_payment_order(p_order uuid, p_gateway_payment_id text, p_paid_amount numeric) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  o erp.payment_orders;
  v_res jsonb;
  v_receipt uuid;
begin
  select * into o from erp.payment_orders where id = p_order for update;
  if o.id is null then raise exception 'payment order not found' using errcode = '22023'; end if;
  if not app.org_has_product(o.org_id, 'erp') then raise exception 'ERP is not active for this school' using errcode = '42501'; end if;
  if o.status = 'paid' then return o.receipt_id; end if;
  if o.status <> 'created' then raise exception 'payment order is %', o.status using errcode = '22023'; end if;
  if p_paid_amount is distinct from o.amount then raise exception 'paid amount does not match the order' using errcode = '22023'; end if;
  v_res := erp.post_receipts(o.org_id, jsonb_build_object(
      'idempotency_key', 'order:' || o.id::text, 'channel', 'online', 'allocations', o.allocations,
      'payments', jsonb_build_array(jsonb_build_object('mode', 'online', 'amount', o.amount, 'gateway', o.gateway, 'gateway_payment_id', p_gateway_payment_id))),
    null, 'Online payment');
  v_receipt := (v_res->'receipt_ids'->>0)::uuid;
  update erp.payment_orders set status = 'paid', receipt_id = v_receipt where id = o.id;
  return v_receipt;
end $$;

create or replace function erp.fail_payment_order(p_order uuid) returns void
language sql volatile security definer set search_path = '' as $$
  update erp.payment_orders set status = 'failed' where id = p_order and status = 'created'
$$;

-- ---------------------------------------------------------------- CRM hand-off (OQ-16; interface only, no CRM code)
-- Admission / registration money collected in the CRM before the learner exists stays in crm.payments. When the learner is
-- admitted (core.admit_student) and ERP is on, the ERP server calls this with the CRM payment: it creates the admission fee
-- demand, one receipt in the same receipt series, and the voucher. Idempotent on (source, source_ref).
create or replace function erp.post_admission_payment(
  p_student uuid, p_amount numeric, p_mode text, p_source text, p_source_ref text,
  p_reference text default null, p_paid_on date default current_date, p_head_type text default 'admission') returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_s core.students;
  v_key text := left(coalesce(p_source, '') || ':' || coalesce(p_source_ref, ''), 200);
  v_head uuid;
  v_demand uuid;
  v_res jsonb;
begin
  if p_source is null or p_source_ref is null or p_amount is null or p_amount <= 0 then
    raise exception 'source, source_ref and a positive amount are required' using errcode = '22023';
  end if;
  if p_mode is null or p_mode not in ('cash', 'card', 'upi', 'cheque', 'dd', 'bank_transfer', 'online') then
    raise exception 'unknown payment mode' using errcode = '22023';
  end if;
  select * into v_s from core.students s where s.id = p_student;
  if not found then raise exception 'learner not found' using errcode = '22023'; end if;
  if v_s.status = 'archived' then raise exception 'learner is archived' using errcode = '22023'; end if;
  if not app.org_has_product(v_s.org_id, 'erp') then raise exception 'ERP is not active for this school' using errcode = '42501'; end if;
  -- repeated hand-off of the same CRM payment returns the earlier receipt
  select r.id into v_demand from erp.receipts r where r.org_id = v_s.org_id and r.idempotency_key = v_key and r.student_id = p_student;
  if v_demand is not null then return v_demand; end if;
  select id into v_head from erp.fee_heads where org_id = v_s.org_id and type = p_head_type and active order by created_at limit 1;
  if v_head is null then
    insert into erp.fee_heads (org_id, name, type) values (v_s.org_id, initcap(p_head_type) || ' fee', p_head_type) returning id into v_head;
  end if;
  insert into erp.fee_demands (org_id, branch_id, student_id, head_id, label, amount, due_date, note)
  values (v_s.org_id, v_s.branch_id, p_student, v_head, initcap(p_head_type) || ' fee', p_amount, p_paid_on, 'Posted from ' || p_source || ' ' || p_source_ref)
  returning id into v_demand;
  v_res := erp.post_receipts(v_s.org_id, jsonb_build_object(
      'idempotency_key', v_key, 'channel', 'import', 'date', p_paid_on, 'note', 'Posted from ' || p_source || ' ' || p_source_ref,
      'allocations', jsonb_build_array(jsonb_build_object('demand_id', v_demand, 'amount', p_amount)),
      'payments', jsonb_build_array(jsonb_build_object('mode', p_mode, 'amount', p_amount, 'reference', p_reference))),
    null, 'CRM hand-off (' || p_source || ')');
  return (v_res->'receipt_ids'->>0)::uuid;
end $$;

-- ---------------------------------------------------------------- 40_approvals_people.sql
-- Approval side effects, learner exit listener, restricted-data read/save functions, report cards, organisation setup.

-- ---------------------------------------------------------------- approvals (core.approval_requests is the one engine)
-- The decision itself is made in core (core.approval_requests / core.approval_actions). A decided request of type
-- linked_type = concession | refund | receipt_reversal | expense | purchase_request | purchase_order | gate_pass |
-- marks_unlock | gallery | announcement has an ERP side effect; this function applies it. It only follows a decision that
-- is already recorded (status approved / rejected) and is safe to call again: every update is conditional on the pending state.
-- (ERP source: apply_approval in 005_logic_ops.sql.)
create or replace function erp.apply_approval(p_request uuid) returns text
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  a core.approval_requests;
  v_ok boolean;
  v_otp text;
  c erp.concessions;
begin
  if v_org is null or not app.user_has_product(v_org, 'erp') or app.my_member_kind() not in ('staff', 'support') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into a from core.approval_requests r where r.id = p_request and r.org_id = v_org;
  if not found or a.product_key <> 'erp' then raise exception 'approval request not found' using errcode = '22023'; end if;
  if a.status not in ('approved', 'rejected') then raise exception 'the request is still %', a.status using errcode = '22023'; end if;
  v_ok := a.status = 'approved';
  case a.linked_type
    when 'concession' then
      update erp.concessions set status = case when v_ok then 'approved' else 'rejected' end, approved_at = now()
       where id = a.linked_id and org_id = v_org and status = 'pending' returning * into c;
      if v_ok and c.id is not null then perform erp.apply_concession(c.id); end if;
    when 'refund' then
      update erp.refunds set status = case when v_ok then 'approved' else 'rejected' end where id = a.linked_id and org_id = v_org and status = 'pending';
    when 'receipt_reversal' then
      if v_ok and exists (select 1 from erp.receipts where id = a.linked_id and org_id = v_org and status = 'valid') then
        perform erp.reverse_receipt(a.linked_id, coalesce(a.data->>'reason', 'Approved reversal'));
      end if;
    when 'expense' then
      update erp.expenses set status = case when v_ok then 'approved' else 'rejected' end where id = a.linked_id and org_id = v_org and status = 'requested';
    when 'purchase_request' then
      update erp.purchase_requests set status = case when v_ok then 'approved' else 'rejected' end where id = a.linked_id and org_id = v_org and status = 'requested';
    when 'purchase_order' then
      update erp.purchase_orders set status = case when v_ok then 'approved' else 'cancelled' end where id = a.linked_id and org_id = v_org and status = 'draft';
    when 'gate_pass' then
      update erp.gate_passes set status = case when v_ok then 'approved' else 'rejected' end where id = a.linked_id and org_id = v_org and status = 'requested';
      if v_ok and found then
        v_otp := lpad(floor(random() * 1000000)::integer::text, 6, '0');
        insert into private.gate_pass_otps (org_id, pass_id, student_id, otp)
        select g.org_id, g.id, g.student_id, v_otp from erp.gate_passes g where g.id = a.linked_id and g.org_id = v_org
        on conflict (org_id, pass_id) do nothing;
      end if;
    when 'marks_unlock' then
      if v_ok then update erp.assessments set status = 'open' where id = a.linked_id and org_id = v_org and status in ('locked', 'published'); end if;
    when 'gallery' then
      update erp.gallery_albums set status = case when v_ok then 'approved' else 'draft' end where id = a.linked_id and org_id = v_org and status = 'pending';
    when 'announcement' then
      update erp.announcements set status = case when v_ok then 'scheduled' else 'rejected' end where id = a.linked_id and org_id = v_org and status = 'pending';
    else
      return 'nothing to apply';
  end case;
  return a.status;
end $$;

-- ---------------------------------------------------------------- learner leaves the school (ERP listener, MAP B.7)
-- core.change_student_status() only changes the status; fees, transport, hostel and the alumni record follow here.
create or replace function erp.apply_student_exit(p_student uuid, p_to text, p_date date default current_date) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  v_s core.students;
begin
  select * into v_s from core.students s where s.id = p_student and s.org_id = v_org;
  if v_org is null or not found or not app.user_has_product(v_org, 'erp') or not app.can('erp', 'students', 'edit', v_org, v_s.branch_id, null) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_to not in ('withdrawn', 'alumni', 'transferred') or v_s.status <> p_to then
    raise exception 'the learner is not % (change the status with core.change_student_status first)', p_to using errcode = '22023';
  end if;
  update erp.fee_demands set status = 'cancelled', note = trim(coalesce(note, '') || ' Cancelled: student ' || p_to)
   where org_id = v_org and student_id = p_student and due_date > p_date and paid = 0 and status = 'due';
  update erp.student_transport set active = false, end_date = p_date where org_id = v_org and student_id = p_student and active;
  update erp.hostel_allocations set active = false, end_date = p_date where org_id = v_org and student_id = p_student and active;
  update core.enrolments set status = case when p_to = 'transferred' then 'transferred' else 'left' end, end_date = p_date
   where org_id = v_org and student_id = p_student and status = 'active';
  if p_to = 'alumni' then
    insert into erp.alumni_profiles (org_id, student_id, batch_year) values (v_org, p_student, extract(year from p_date)::integer)
    on conflict (org_id, student_id) do nothing;
  end if;
end $$;

-- ---------------------------------------------------------------- restricted data: read and save through functions (logged)
-- erp.student_sensitive and erp.staff_payroll have no direct table access. Health data: staff with student_sensitive.view
-- or the learner's own guardian / the learner. Payroll identity and bank data: staff with payroll.view or the person themself.
create or replace function erp.read_student_sensitive(p_student uuid) returns erp.student_sensitive
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  v_s core.students;
  r erp.student_sensitive;
begin
  select * into v_s from core.students s where s.id = p_student and s.org_id = v_org;
  if v_org is null or not found or not app.user_has_product(v_org, 'erp')
     or not (p_student = any(app.my_learner_ids()) or app.can('erp', 'student_sensitive', 'view', v_org, v_s.branch_id, null)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into r from erp.student_sensitive x where x.org_id = v_org and x.student_id = p_student;
  perform erp.log_view('student_sensitive', p_student, 'Health and statutory fields viewed');
  return r;
end $$;

create or replace function erp.save_student_sensitive(p_student uuid, p_data jsonb) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  v_s core.students;
  v_id uuid;
begin
  select * into v_s from core.students s where s.id = p_student and s.org_id = v_org;
  if v_org is null or not found or not app.user_has_product(v_org, 'erp') or not app.can('erp', 'student_sensitive', 'edit', v_org, v_s.branch_id, null) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  insert into erp.student_sensitive (org_id, student_id, medical_notes, doctor_name, doctor_phone, emergency_contact, vaccination, aadhaar_last4, cwsn, cwsn_details)
  values (v_org, p_student, p_data->>'medical_notes', p_data->>'doctor_name', p_data->>'doctor_phone', p_data->>'emergency_contact',
          p_data->>'vaccination', p_data->>'aadhaar_last4', coalesce((p_data->>'cwsn')::boolean, false), p_data->>'cwsn_details')
  on conflict (org_id, student_id) do update set
    medical_notes = excluded.medical_notes, doctor_name = excluded.doctor_name, doctor_phone = excluded.doctor_phone,
    emergency_contact = excluded.emergency_contact, vaccination = excluded.vaccination, aadhaar_last4 = excluded.aadhaar_last4,
    cwsn = excluded.cwsn, cwsn_details = excluded.cwsn_details
  returning id into v_id;
  return v_id;
end $$;

create or replace function erp.read_staff_payroll(p_staff uuid) returns erp.staff_payroll
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  v_st core.staff;
  r erp.staff_payroll;
begin
  select * into v_st from core.staff s where s.id = p_staff and s.org_id = v_org;
  if v_org is null or not found or not app.user_has_product(v_org, 'erp')
     or not (p_staff = app.my_core_staff_id() or app.can('erp', 'payroll', 'view', v_org, v_st.branch_id, null)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into r from erp.staff_payroll x where x.org_id = v_org and x.staff_id = p_staff;
  perform erp.log_view('staff_payroll', p_staff, 'Bank, tax and statutory identity viewed');
  return r;
end $$;

create or replace function erp.save_staff_payroll(p_staff uuid, p_data jsonb) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  v_st core.staff;
  v_id uuid;
begin
  select * into v_st from core.staff s where s.id = p_staff and s.org_id = v_org;
  if v_org is null or not found or not app.user_has_product(v_org, 'erp') or not app.can('erp', 'payroll', 'edit', v_org, v_st.branch_id, null) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  insert into erp.staff_payroll (org_id, staff_id, bank_name, bank_account, ifsc, pan, uan, esi_no, aadhaar_last4, tax_regime, address, emergency_contact)
  values (v_org, p_staff, p_data->>'bank_name', p_data->>'bank_account', p_data->>'ifsc', upper(p_data->>'pan'), p_data->>'uan', p_data->>'esi_no',
          p_data->>'aadhaar_last4', coalesce(p_data->>'tax_regime', 'new'), p_data->>'address', p_data->>'emergency_contact')
  on conflict (org_id, staff_id) do update set
    bank_name = excluded.bank_name, bank_account = excluded.bank_account, ifsc = excluded.ifsc, pan = excluded.pan, uan = excluded.uan,
    esi_no = excluded.esi_no, aadhaar_last4 = excluded.aadhaar_last4, tax_regime = excluded.tax_regime, address = excluded.address,
    emergency_contact = excluded.emergency_contact
  returning id into v_id;
  return v_id;
end $$;

-- ---------------------------------------------------------------- report cards, documents
-- Family (published only) and staff open a report card here so that the view is logged; the count goes up for families.
create or replace function erp.open_report_card(p_id uuid) returns erp.report_cards
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  r erp.report_cards;
  v_staff boolean;
begin
  select * into r from erp.report_cards c where c.id = p_id and c.org_id = v_org;
  if v_org is null or not found or not app.user_has_product(v_org, 'erp') then raise exception 'not allowed' using errcode = '42501'; end if;
  v_staff := app.can('erp', 'marks', 'view', v_org, r.branch_id, null);
  if not v_staff and not (r.status = 'published' and r.student_id = any(app.my_learner_ids())) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not v_staff then
    update erp.report_cards set views = views + 1 where id = r.id;
    perform erp.log_view('report_cards', p_id, 'Opened by family');
  end if;
  return r;
end $$;

-- Verification of a certificate or report card by its code. NOT granted to anon (nothing in this schema is): the public QR page
-- calls this from the ERP server. Returns only what a verifier needs.
create or replace function erp.verify_document(p_code text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(
    (select jsonb_build_object('kind', 'document', 'type', d.type, 'title', d.title, 'number', d.number, 'status', d.status,
              'issued_on', d.issued_on, 'school', o.name,
              'student', (select s.full_name from core.students s where s.id = d.student_id))
       from erp.issued_documents d join core.organizations o on o.id = d.org_id
      where d.verify_code = p_code and length(p_code) >= 10 and app.org_has_product(d.org_id, 'erp')),
    (select jsonb_build_object('kind', 'report_card', 'type', 'Report card', 'title', r.term, 'status', r.status,
              'issued_on', r.published_at::date, 'school', o.name,
              'student', (select s.full_name from core.students s where s.id = r.student_id))
       from erp.report_cards r join core.organizations o on o.id = r.org_id
      where r.verify_code = p_code and r.status = 'published' and length(p_code) >= 10 and app.org_has_product(r.org_id, 'erp')))
$$;

-- ---------------------------------------------------------------- organisation setup
-- Roles, default chart of accounts and module switches for a school that has just got ERP. Idempotent. Callable by the
-- platform (service role / platform admin) or by an admin of the school itself (setup.configure), for that school only.
create or replace function erp.setup_org(p_org uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if not (app.is_platform_admin() or coalesce(auth.role(), '') = 'service_role'
          or (p_org = app.current_org_id() and app.user_has_product(p_org, 'erp') and app.can('erp', 'setup', 'configure', p_org, null, null))) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform erp.seed_roles(p_org);
  insert into erp.accounts (org_id, code, name, type, is_system) values
    (p_org, '1000', 'Cash in hand', 'asset', true), (p_org, '1010', 'Bank', 'asset', true), (p_org, '1100', 'Fee receivable', 'asset', true),
    (p_org, '2000', 'Caution deposits and advances', 'liability', true), (p_org, '2100', 'Payroll payable', 'liability', true),
    (p_org, '4000', 'Fee income', 'income', true), (p_org, '4100', 'Other income', 'income', true),
    (p_org, '5000', 'Salaries', 'expense', true), (p_org, '5100', 'Operating expenses', 'expense', true)
  on conflict (org_id, code) do nothing;
end $$;

-- ---------------------------------------------------------------- 50_ops.sql
-- Gate pass handover, PTM booking, online tests, canteen/store counter, driver and attendant app.
-- Ports of verify_gate_pass, book_ptm_slot, get_test_questions, submit_test, pos_sale and driver_* (005_logic_ops.sql).
-- Family and driver users have no table access for these flows: they call these functions, which check who they are.

-- ---------------------------------------------------------------- gate pass (SAF-02)
-- The guardian sees the OTP of an approved pass for their own child; gate staff verify what the collector says.
create or replace function erp.my_gate_pass_otp(p_pass uuid) returns text
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  g erp.gate_passes;
begin
  select * into g from erp.gate_passes x where x.id = p_pass and x.org_id = v_org;
  if v_org is null or not found or not app.user_has_product(v_org, 'erp') or g.status <> 'approved'
     or not (g.student_id = any(app.my_learner_ids())) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return (select o.otp from private.gate_pass_otps o where o.org_id = v_org and o.pass_id = p_pass);
end $$;

create or replace function erp.verify_gate_pass(p_pass uuid, p_otp text) returns text
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  g erp.gate_passes;
  v_name text;
begin
  select * into g from erp.gate_passes x where x.id = p_pass and x.org_id = v_org;
  if v_org is null or not found or not app.user_has_product(v_org, 'erp') or not app.can('erp', 'gate', 'edit', v_org, g.branch_id, null) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if g.status <> 'approved' then raise exception 'This pass is % and cannot be used.', g.status using errcode = '22023'; end if;
  if not app.rate_limit_hit('gatepass:' || p_pass::text, 5, 900, v_org) then
    raise exception 'Too many tries for this pass. Ask the front office.' using errcode = '54000';
  end if;
  if not exists (select 1 from private.gate_pass_otps o where o.org_id = v_org and o.pass_id = p_pass and o.otp = btrim(p_otp)) then
    perform erp.notify_roles(v_org, array['principal', 'front_office'], g.branch_id, 'gate.wrong_otp', 'Wrong OTP at the gate',
      'A collector gave a wrong OTP. The student was not handed over.', '/gate');
    return 'mismatch';
  end if;
  update erp.gate_passes set status = 'handed_over', handed_over_at = now(), verified_by_user_id = app.uid(),
         verified_by_name = (select u.display_name from core.org_users u where u.user_id = app.uid())
   where id = p_pass;
  select s.full_name into v_name from core.students s where s.id = g.student_id;
  perform erp.notify_guardians(g.student_id, 'gate.handed_over', 'Handed over',
    v_name || ' was handed over to ' || coalesce(g.collector_name, 'the collector') || ' at ' || to_char(now() at time zone 'Asia/Kolkata', 'HH12:MI AM'), '/parent');
  return 'ok';
end $$;

-- ---------------------------------------------------------------- PTM booking (EVT-02)
create or replace function erp.book_ptm_slot(p_slot uuid, p_student uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
begin
  if v_org is null or not app.user_has_product(v_org, 'erp') or not (p_student = any(app.my_learner_ids())) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  update erp.ptm_slots set status = 'booked', student_id = p_student, booked_by = app.uid()
   where id = p_slot and org_id = v_org and status = 'open';
  if not found then raise exception 'That slot has just been taken. Please pick another.' using errcode = '55000'; end if;
end $$;

-- ---------------------------------------------------------------- online tests (EXM-05, EXM-06): answers never reach the student's browser
-- Questions are core.question_bank rows: content = {text, type, options, answer}.
create or replace function erp.get_test_questions(p_test uuid) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  t erp.online_tests;
begin
  select * into t from erp.online_tests x where x.id = p_test and x.org_id = v_org;
  if v_org is null or not found or not app.user_has_product(v_org, 'erp') then raise exception 'Test not found.' using errcode = '22023'; end if;
  if not (app.can('erp', 'exams', 'view', v_org, t.branch_id, null)
          or (t.status = 'live' and t.section_id = any(app.my_learner_section_ids()))) then
    raise exception 'This test is not open to you.' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', q.id, 'question', q.content->>'text', 'type', coalesce(q.content->>'type', 'mcq'),
                                        'options', q.content->'options', 'marks', coalesce(q.marks, 1))
                     order by case when t.randomise then random() else 0 end)
      from core.question_bank q
     where q.org_id = t.org_id and q.deleted_at is null and q.id in (select (x #>> '{}')::uuid from jsonb_array_elements(t.question_ids) x)), '[]'::jsonb);
end $$;

create or replace function erp.submit_test(p_test uuid, p_student uuid, p_answers jsonb, p_tab_switches integer default 0) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  t erp.online_tests;
  q record;
  v_score numeric := 0;
  v_max numeric := 0;
  got numeric;
  v_an jsonb := '{}'::jsonb;
  given text;
  v_bloom text;
  v_marks numeric;
begin
  select * into t from erp.online_tests x where x.id = p_test and x.org_id = v_org;
  if v_org is null or not found or t.status <> 'live' or not app.user_has_product(v_org, 'erp') then
    raise exception 'This test is not open.' using errcode = '22023';
  end if;
  if not (p_student = any(app.my_learner_ids())) then raise exception 'Not allowed.' using errcode = '42501'; end if;
  if exists (select 1 from erp.test_attempts a where a.org_id = v_org and a.test_id = p_test and a.student_id = p_student and a.submitted_at is not null) then
    raise exception 'You have already submitted this test.' using errcode = '22023';
  end if;
  for q in select * from core.question_bank where org_id = t.org_id and id in (select (x #>> '{}')::uuid from jsonb_array_elements(t.question_ids) x) loop
    given := lower(btrim(coalesce(p_answers->>(q.id::text), '')));
    v_marks := coalesce(q.marks, 1);
    v_bloom := coalesce(q.bloom, 'understand');
    got := case when coalesce(q.content->>'type', 'mcq') in ('mcq', 'true_false', 'short') and given <> ''
                 and given = lower(btrim(coalesce(q.content->>'answer', ''))) then v_marks else 0 end;
    v_score := v_score + got;
    v_max := v_max + v_marks;
    v_an := jsonb_set(v_an, array[v_bloom], jsonb_build_object(
      'score', coalesce((v_an->v_bloom->>'score')::numeric, 0) + got, 'max', coalesce((v_an->v_bloom->>'max')::numeric, 0) + v_marks));
  end loop;
  insert into erp.test_attempts (org_id, test_id, student_id, answers, score, max_score, submitted_at, tab_switches, analysis)
  values (v_org, p_test, p_student, p_answers, v_score, v_max, now(), coalesce(p_tab_switches, 0), v_an)
  on conflict (org_id, test_id, student_id) do update set answers = excluded.answers, score = excluded.score, max_score = excluded.max_score,
    submitted_at = now(), tab_switches = excluded.tab_switches, analysis = excluded.analysis;
  -- marks of an assessment are written only while it is still open for entry (locked and published marks never change)
  if t.assessment_id is not null and erp.assessment_status(v_org, t.assessment_id) in ('open', 'submitted') then
    insert into erp.assessment_results (org_id, assessment_id, student_id, marks) values (v_org, t.assessment_id, p_student, v_score)
    on conflict (org_id, assessment_id, student_id) do update set marks = excluded.marks;
  end if;
  return jsonb_build_object('score', v_score, 'max', v_max);
end $$;

-- ---------------------------------------------------------------- store and canteen counter, wallet (CAN-01, CAN-02)
-- p = { counter, student_id, payment_mode, lines: [{item_id, qty, price, variant?}] }
create or replace function erp.pos_sale(p jsonb) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  w erp.student_wallets;
  v_total numeric;
  v_today numeric;
  l jsonb;
  v_id uuid;
  v_student uuid := nullif(p->>'student_id', '')::uuid;
  v_mode text := coalesce(p->>'payment_mode', 'wallet');
  blocked text;
begin
  if v_org is null or not app.user_has_product(v_org, 'erp') or not app.can('erp', 'inventory', 'create', v_org, null, null) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select coalesce(sum((x->>'qty')::numeric * (x->>'price')::numeric), 0) into v_total from jsonb_array_elements(p->'lines') x;
  if v_total <= 0 then raise exception 'Add at least one item.' using errcode = '22023'; end if;
  if v_mode = 'wallet' then
    select * into w from erp.student_wallets x where x.student_id = v_student and x.org_id = v_org for update;
    if w.id is null or not w.active then raise exception 'This student has no active wallet.' using errcode = '22023'; end if;
    for l in select * from jsonb_array_elements(p->'lines') loop
      select i.name into blocked from erp.items i
       where i.id = (l->>'item_id')::uuid and i.org_id = v_org and (',' || lower(coalesce(w.blocked_items, '')) || ',') like '%,' || lower(i.name) || ',%';
      if blocked is not null then raise exception '% is blocked by the parent for this student.', blocked using errcode = '22023'; end if;
    end loop;
    if w.balance < v_total then raise exception 'Wallet balance is Rs % but the bill is Rs %.', w.balance, v_total using errcode = '22023'; end if;
    select coalesce(sum(t.amount), 0) into v_today from erp.student_wallet_txns t where t.wallet_id = w.id and t.type = 'purchase' and t.at::date = current_date;
    if w.daily_limit is not null and v_today + v_total > w.daily_limit then
      raise exception 'This goes over the daily spend limit of Rs % set by the parent.', w.daily_limit using errcode = '22023';
    end if;
    update erp.student_wallets set balance = balance - v_total where id = w.id;
    insert into erp.student_wallet_txns (org_id, wallet_id, student_id, type, amount, note)
    values (v_org, w.id, v_student, 'purchase', v_total, coalesce(p->>'counter', 'canteen') || ' purchase');
  end if;
  insert into erp.sales (org_id, branch_id, counter, student_id, lines, total, payment_mode, sold_by_user_id, sold_by_name)
  values (v_org, erp.my_branch_id(), coalesce(p->>'counter', 'canteen'), v_student, p->'lines', v_total, v_mode, app.uid(),
          (select u.display_name from core.org_users u where u.user_id = app.uid())) returning id into v_id;
  insert into erp.stock_movements (org_id, branch_id, item_id, qty, type, ref, variant)
  select v_org, erp.my_branch_id(), (x->>'item_id')::uuid, -(x->>'qty')::numeric, 'sale', v_id::text, x->>'variant'
    from jsonb_array_elements(p->'lines') x where x->>'item_id' is not null;
  return v_id;
end $$;

-- Top-up (or adjustment) of a learner's wallet at the counter; the gateway top-up is posted by the server with the same function.
create or replace function erp.wallet_topup(p_student uuid, p_amount numeric, p_ref text default null, p_type text default 'topup') returns numeric
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_org uuid := app.current_org_id();
  w erp.student_wallets;
begin
  if v_org is null or not app.user_has_product(v_org, 'erp') or not app.can('erp', 'canteen', 'create', v_org, null, null) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_amount is null or p_amount <= 0 or p_type not in ('topup', 'refund', 'adjust') then raise exception 'invalid top-up' using errcode = '22023'; end if;
  if not exists (select 1 from core.students s where s.id = p_student and s.org_id = v_org) then raise exception 'learner not found' using errcode = '22023'; end if;
  insert into erp.student_wallets (org_id, student_id) values (v_org, p_student) on conflict (org_id, student_id) do nothing;
  select * into w from erp.student_wallets x where x.org_id = v_org and x.student_id = p_student for update;
  update erp.student_wallets set balance = balance + p_amount where id = w.id returning * into w;
  insert into erp.student_wallet_txns (org_id, wallet_id, student_id, type, amount, ref) values (v_org, w.id, p_student, p_type, p_amount, p_ref);
  return w.balance;
end $$;

-- ---------------------------------------------------------------- driver and attendant app (TR-04): no table access, only these actions
create or replace function erp.route_ok(p_route uuid) returns boolean
language plpgsql stable security definer set search_path = '' as $$
begin
  return exists (select 1 from erp.routes r
                  where r.id = p_route and r.org_id = app.current_org_id() and app.user_has_product(r.org_id, 'erp')
                    and (app.can('erp', 'transport', 'edit', r.org_id, r.branch_id, null)
                         or r.driver_id = app.my_core_staff_id() or r.attendant_id = app.my_core_staff_id()));
end $$;

create or replace function erp.driver_routes() returns table (id uuid, name text, vehicle text, running_trip uuid)
language plpgsql stable security definer set search_path = '' as $$
begin
  return query
    select r.id, r.name, v.reg_no,
           (select t.id from erp.trips t where t.route_id = r.id and t.status = 'running' order by t.started_at desc limit 1)
      from erp.routes r left join erp.vehicles v on v.id = r.vehicle_id and v.org_id = r.org_id
     where r.org_id = app.current_org_id() and r.active and erp.route_ok(r.id) order by r.name;
end $$;

create or replace function erp.driver_trip_start(p_route uuid, p_direction text default 'pickup') returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_id uuid;
  r erp.routes;
begin
  if not erp.route_ok(p_route) then raise exception 'This route is not assigned to you.' using errcode = '42501'; end if;
  if p_direction not in ('pickup', 'drop', 'special') then raise exception 'unknown direction' using errcode = '22023'; end if;
  select * into r from erp.routes where id = p_route;
  select id into v_id from erp.trips where org_id = r.org_id and route_id = p_route and status = 'running' limit 1;
  if v_id is not null then return v_id; end if;
  insert into erp.trips (org_id, branch_id, route_id, direction) values (r.org_id, r.branch_id, p_route, p_direction) returning id into v_id;
  insert into core.notifications (org_id, user_id, product_key, event_key, title, body, link)
  select distinct r.org_id, g.user_id, 'erp', 'transport.trip_started', 'Bus started', r.name || ' has started its ' || p_direction || ' trip.', '/parent/bus'
    from erp.student_transport st
    join core.students s on s.org_id = st.org_id and s.id = st.student_id
    join core.guardians g on g.org_id = s.org_id and g.household_id = s.household_id
   where st.org_id = r.org_id and st.route_id = p_route and st.active and g.user_id is not null;
  return v_id;
end $$;

create or replace function erp.driver_trip_students(p_trip uuid) returns table (student_id uuid, name text, stop text, sort integer, last_event text)
language plpgsql stable security definer set search_path = '' as $$
begin
  return query
    select s.id, s.full_name, sp.name, coalesce(sp.sort, 0),
           (select e.type from erp.trip_events e where e.org_id = t.org_id and e.trip_id = t.id and e.student_id = s.id order by e.at desc limit 1)
      from erp.trips t
      join erp.student_transport st on st.org_id = t.org_id and st.route_id = t.route_id and st.active
      join core.students s on s.org_id = st.org_id and s.id = st.student_id and s.status = 'active'
      left join erp.stops sp on sp.org_id = st.org_id and sp.id = st.stop_id
     where t.id = p_trip and t.org_id = app.current_org_id() and erp.route_ok(t.route_id)
     order by 4, 2;
end $$;

create or replace function erp.driver_mark(p_trip uuid, p_student uuid, p_type text, p_lat numeric default null, p_lng numeric default null, p_note text default null)
returns void language plpgsql volatile security definer set search_path = '' as $$
declare
  t erp.trips;
  v_name text;
begin
  select * into t from erp.trips where id = p_trip and org_id = app.current_org_id();
  if t.id is null or not erp.route_ok(t.route_id) then raise exception 'This trip is not assigned to you.' using errcode = '42501'; end if;
  if p_type not in ('boarded', 'dropped', 'absent', 'sos', 'delay') then raise exception 'Unknown event.' using errcode = '22023'; end if;
  if p_student is not null and not exists (select 1 from erp.student_transport st where st.org_id = t.org_id and st.route_id = t.route_id and st.student_id = p_student and st.active) then
    raise exception 'That student is not on this route.' using errcode = '22023';
  end if;
  insert into erp.trip_events (org_id, trip_id, student_id, type, lat, lng, note) values (t.org_id, p_trip, p_student, p_type, p_lat, p_lng, p_note);
  if p_type in ('boarded', 'dropped') and p_student is not null then
    select s.full_name into v_name from core.students s where s.id = p_student;
    perform erp.notify_guardians(p_student, 'transport.' || p_type, v_name || ' ' || p_type, 'At ' || to_char(now() at time zone 'Asia/Kolkata', 'HH12:MI AM'), '/parent/bus');
  elsif p_type = 'sos' then
    perform erp.notify_roles(t.org_id, array['transport', 'principal', 'group_admin'], t.branch_id, 'transport.sos', 'SOS from a bus', coalesce(p_note, 'The driver pressed SOS.'), '/transport/live');
  elsif p_type = 'delay' then
    update erp.trips set delay_minutes = coalesce(nullif(p_note, '')::integer, 15) where id = p_trip;
    insert into core.notifications (org_id, user_id, product_key, event_key, title, body, link)
    select distinct t.org_id, g.user_id, 'erp', 'transport.delay', 'Bus running late',
           'Your bus is running about ' || coalesce(nullif(p_note, ''), '15') || ' minutes late.', '/parent/bus'
      from erp.student_transport st
      join core.students s on s.org_id = st.org_id and s.id = st.student_id
      join core.guardians g on g.org_id = s.org_id and g.household_id = s.household_id
     where st.org_id = t.org_id and st.route_id = t.route_id and st.active and g.user_id is not null;
    perform erp.notify_roles(t.org_id, array['transport'], t.branch_id, 'transport.delay', 'Bus delay reported', null, '/transport/live');
  end if;
end $$;

create or replace function erp.driver_position(p_trip uuid, p_lat numeric, p_lng numeric, p_speed numeric default null) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  t erp.trips;
begin
  select * into t from erp.trips where id = p_trip and org_id = app.current_org_id() and status = 'running';
  if t.id is null or not erp.route_ok(t.route_id) then return; end if;
  update erp.trips set last_lat = p_lat, last_lng = p_lng, last_speed = p_speed, last_at = now() where id = p_trip;
  insert into erp.trip_positions (org_id, trip_id, lat, lng, speed) values (t.org_id, p_trip, p_lat, p_lng, p_speed);
  if coalesce(p_speed, 0) > 60 and not exists (select 1 from erp.trip_events e where e.org_id = t.org_id and e.trip_id = p_trip and e.type = 'overspeed' and e.at > now() - interval '5 minutes') then
    insert into erp.trip_events (org_id, trip_id, type, lat, lng, note) values (t.org_id, p_trip, 'overspeed', p_lat, p_lng, round(p_speed) || ' km/h');
    perform erp.notify_roles(t.org_id, array['transport'], t.branch_id, 'transport.overspeed', 'Over-speed alert', round(p_speed) || ' km/h', '/transport/live');
  end if;
end $$;

create or replace function erp.driver_trip_end(p_trip uuid) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  t erp.trips;
begin
  select * into t from erp.trips where id = p_trip and org_id = app.current_org_id();
  if t.id is null or not erp.route_ok(t.route_id) then raise exception 'This trip is not assigned to you.' using errcode = '42501'; end if;
  update erp.trips set status = 'completed', ended_at = now() where id = p_trip;
end $$;
